def esc(t):
    t = t.replace("\\","\\\\").replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")
    t = t.replace("'","\\'").replace('"','\\"').replace("\n","\\n")
    return t

import os, sys
base = sys.argv[1]
for idx, folder in enumerate(["values","values-nl","values-de"]):
    os.makedirs(os.path.join(base, folder), exist_ok=True)
    out = ['<?xml version="1.0" encoding="utf-8"?>', '<!-- Gegenereerd: niet met de hand aanpassen -->', '<resources>']
    for k,v in S.items():
        if k == "app_name" and idx: continue
        out.append(f'    <string name="{k}">{esc(v[idx])}</string>')
    for k,v in P.items():
        one, other = v[idx]
        out.append(f'    <plurals name="{k}">\n        <item quantity="one">{esc(one)}</item>\n        <item quantity="other">{esc(other)}</item>\n    </plurals>')
    out.append('</resources>\n')
    open(os.path.join(base, folder, "strings.xml"), "w", encoding="utf-8").write("\n".join(out))
print("ok", len(S), len(P))
